package in.tutorlink.controller; import in.tutorlink.entity.*; import in.tutorlink.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController {final UserRepository users;final TutorProfileRepository tutors;final TuitionRepository tuition;final ApplicationRepository apps;public AdminController(UserRepository u,TutorProfileRepository t,TuitionRepository q,ApplicationRepository a){users=u;tutors=t;tuition=q;apps=a;} @GetMapping("/users") List<User> users(){return users.findAll();}@GetMapping("/statistics") Map<String,Long> stats(){return Map.of("students",users.countByRole(Role.STUDENT),"parents",users.countByRole(Role.PARENT),"tutors",(long)tutors.findAll().size(),"requirements",tuition.countByActiveTrue(),"applications",apps.count());}@PutMapping("/verification/{id}") TutorProfile verify(@PathVariable Long id,@RequestBody Map<String,String>b){var p=tutors.findById(id).orElseThrow();p.verificationStatus=VerificationStatus.valueOf(b.get("status"));return tutors.save(p);}}
